/**
 * SlayerWings Engine Daemon Configuration Generator
 * Produces production SlayerWings v1.0.0 config.yml
 */

export function generateWingsConfig(node, options = {}) {
  const token = options.token || `sn_wing_${Math.random().toString(36).substring(2, 15)}_${Math.random().toString(36).substring(2, 15)}`;
  const tokenId = options.tokenId || Math.random().toString(36).substring(2, 10);

  return `# ========================================================
# SlayerWings Engine Daemon Configuration (v1.0.0)
# Generated by SlayerNode Panel for ${node.name}
# Documentation: https://slayernode.xyz/docs/slayerwings
# ========================================================
debug: false
uuid: ${node.uuid}
token_id: ${tokenId}
token: ${token}
api:
  host: 0.0.0.0
  port: ${node.daemon_listen || 8443}
  ssl:
    enabled: ${node.scheme === 'https'}
    cert: /etc/letsencrypt/live/${node.fqdn}/fullchain.pem
    key: /etc/letsencrypt/live/${node.fqdn}/privkey.pem
  upload_limit: ${node.upload_size || 500}
system:
  root_directory: ${node.daemon_base || '/var/lib/slayerwings/volumes'}
  log_directory: /var/log/slayerwings
  data: /var/lib/slayerwings
  archive_directory: /var/lib/slayerwings/backups
  backup_retention: 7
  sftp:
    bind_port: ${node.daemon_sftp || 2202}
allowed_mounts: []
remote: ${options.remoteUrl || 'http://localhost:3000'}
docker:
  network:
    name: slayernode_nw
    driver: bridge
    interface: 172.18.0.1
    dns:
      - 1.1.1.1
      - 8.8.8.8
`;
}
